<script setup lang="ts">
import {computed,ref,watch,onDeactivated} from 'vue';
import type {Game,Action} from '../../src/full/types.ts';
import * as C from '../../src/full/content.ts';
import {previewActivity,type Activity,type CraftPlan,type ForgePlan} from '../../src/full/activity.ts';
import {previewAction} from '../../src/full/queries.ts';
import type {TrackingTarget} from '../../src/full/goals.ts';
import {pageSlice} from './play-flow';
import AssetImage from './AssetImage.vue';
import GameIcon from './GameIcon.vue';
import CataloguePager from './CataloguePager.vue';
type Limits={stoneBudget:number;stoneReserve:number;monthBudget:number;remainingMonthsReserve:number;itemReserves:Record<string,number>};
const props=defineProps<{game:Game;mode:'craft'|'forge';busy:boolean;available:boolean;running:boolean;highlight:string;savedPlan:CraftPlan|ForgePlan|null;activity:Activity|null;runtime:{id:string;totalMs:number;remainingMs:number;phase:string}|null;embedded?:boolean;minimal?:boolean;consumption:(action:Action)=>string}>();
const emit=defineEmits<{start:[CraftPlan|ForgePlan];track:[TrackingTarget];act:[Action];travel:[CraftPlan|ForgePlan]}>();
const limitsEdited=ref(false);
const selected=ref(''),page=ref(0),future=ref(false),cycles=ref<number|'target'>(5),targetQuantity=ref(1),targetCycles=ref(50),dialog=ref<HTMLDialogElement>();
const copy=(l:Limits):Limits=>({stoneBudget:l.stoneBudget,stoneReserve:l.stoneReserve,monthBudget:l.monthBudget,remainingMonthsReserve:l.remainingMonthsReserve,itemReserves:{...l.itemReserves}});
const limits=ref<Limits>({stoneBudget:0,stoneReserve:0,monthBudget:0,remainingMonthsReserve:1,itemReserves:{}}),draft=ref<Limits>(copy(limits.value));
const rows=computed(()=>props.mode==='craft'?Object.entries(C.recipes).filter(([,r])=>future.value||C.rank(r.min)<=C.rank(props.game.core.player.realm)).map(([id,r])=>({id,name:r.name,icon:r.output,min:r.min})):Object.entries(C.relics).filter(([id])=>future.value||props.game.ownedRelics.includes(id)||C.rank(props.game.core.player.realm)>=C.rank('golden')).map(([id,r])=>({id,name:r.name,icon:id,min:'golden' as C.RealmId})));
const paged=computed(()=>pageSlice(rows.value,page.value,4));
const recipe=computed(()=>props.mode==='craft'?C.recipes[selected.value]:null),relic=computed(()=>props.mode==='forge'?C.relics[selected.value]:null);
const unit=computed(()=>recipe.value?{stones:recipe.value.stones,months:recipe.value.months,items:recipe.value.inputs}:relic.value?{stones:relic.value.stones,months:C.actionDurations.forge,items:relic.value.inputs}:null);
const output=computed(()=>recipe.value?C.items[recipe.value.output]:null),owned=computed(()=>props.mode==='forge'&&props.game.ownedRelics.includes(selected.value));
const equipQuote=computed(()=>owned.value?previewAction(props.game,{type:'EQUIP_RELIC',relic:selected.value}):null);
const equipReason=computed(()=>!props.available?'存档未就绪':props.busy?'当前行动进行中':props.running?'当前活动进行中，请先暂停再装备':equipQuote.value?.failure?.message??'');
const plan=computed<CraftPlan|ForgePlan>(()=>props.mode==='craft'?{kind:'craft',recipeId:selected.value,maxCycles:cycles.value==='target'?targetCycles.value:cycles.value,until:cycles.value==='target'?'target':'cycles',targetQuantity:cycles.value==='target'?targetQuantity.value:null,...copy(limits.value)}:{kind:'forge',relicId:selected.value,maxCycles:1,...copy(limits.value)});
const quote=computed(()=>unit.value?previewActivity(props.game,plan.value):null);
const currentActivity=computed(()=>{const a=props.activity;return a?.plan.kind===props.mode&&(a.plan.kind==='craft'?a.plan.recipeId:a.plan.kind==='forge'?a.plan.relicId:'')===selected.value?a:null;});
const activeRuntime=computed(()=>currentActivity.value?.id===props.runtime?.id?props.runtime:null);
const fire=computed(()=>activeRuntime.value?activeRuntime.value.phase==='saving'?'封存成果':(1-activeRuntime.value.remainingMs/activeRuntime.value.totalMs)<.2?'温炉':(1-activeRuntime.value.remainingMs/activeRuntime.value.totalMs)<.8?(props.mode==='craft'?'炼化药性':'淬炼器纹'):(props.mode==='craft'?'凝丹':'器物成形'):currentActivity.value?.status==='paused'?'炉火暂歇':currentActivity.value?.status==='stopped'?(currentActivity.value.completedCycles?'成果已保存':'安排已停止'):'待启炉');
function resetLimits(n:number){if(!unit.value)return;limits.value={stoneBudget:unit.value.stones*n,stoneReserve:0,monthBudget:unit.value.months*n,remainingMonthsReserve:1,itemReserves:{}};}
function restorePlan(){const p=props.savedPlan;if(!p||p.kind!==props.mode||(p.kind==='craft'?p.recipeId:p.relicId)!==selected.value)return;limits.value=copy(p);limitsEdited.value=true;if(p.kind==='craft'){cycles.value=p.until==='target'?'target':p.maxCycles;targetCycles.value=p.maxCycles;targetQuantity.value=p.targetQuantity??1;}}
function select(id:string){limitsEdited.value=false;selected.value=id;cycles.value=output.value?.kind==='breakthrough'?'target':5;targetQuantity.value=1;targetCycles.value=50;resetLimits(props.mode==='forge'||cycles.value==='target'?1:5);restorePlan();}
function locate(){const prefix=props.mode==='craft'?'craft-':props.highlight.startsWith('equip-relic-')?'equip-relic-':'forge-',id=props.highlight.startsWith(prefix)?props.highlight.slice(prefix.length):'';if((props.mode==='craft'?C.recipes:C.relics)[id]){future.value=true;page.value=Math.max(0,Math.floor(rows.value.findIndex(r=>r.id===id)/4));select(id);}else if(!rows.value.some(r=>r.id===selected.value)&&rows.value.length)select(rows.value[0].id);}
watch([()=>props.game.core.runId,()=>props.mode,()=>props.highlight],locate,{immediate:true});watch(()=>props.savedPlan,restorePlan);function changeFuture(){page.value=0;if(!rows.value.some(r=>r.id===selected.value)){selected.value='';if(rows.value.length)select(rows.value[0].id);}}
function changeCycles(){if(!recipe.value||limitsEdited.value)return;const n=cycles.value==='target'?Math.min(targetCycles.value,Math.max(1,targetQuantity.value-props.game.core.inventory[recipe.value.output])):cycles.value;resetLimits(n);}
function openLimits(){draft.value={...copy(limits.value),itemReserves:Object.fromEntries(Object.keys(unit.value?.items??{}).map(id=>[id,limits.value.itemReserves[id]??0]))};dialog.value?.showModal();}
function applyLimits(){limits.value=copy(draft.value);limitsEdited.value=true;dialog.value?.close();}
function need(id:string){if(!unit.value)return 1;const n=props.mode==='forge'?1:cycles.value==='target'?Math.min(targetCycles.value,Math.max(0,targetQuantity.value-(recipe.value?props.game.core.inventory[recipe.value.output]:0))):cycles.value;return Math.min(C.maxQuantity,Math.max(1,unit.value.items[id]*n+(limits.value.itemReserves[id]??0)));}
const consumptionWarning=computed(()=>selected.value&&!owned.value?props.consumption(props.mode==='craft'?{type:'CRAFT',recipeId:selected.value}:{type:'FORGE',relic:selected.value}):'');
onDeactivated(()=>dialog.value?.close());
const costText=(items:Record<string,number>)=>Object.entries(items).map(([id,n])=>C.items[id].name+' ×'+n).join(' · ');
</script>
<template>
 <section class="production-planner" :class="{'paper':!embedded,'play-catalogue':!embedded,'production-minimal':minimal}" :data-testid="mode==='craft'?'recipe-catalogue':'forging-planner'" tabindex="-1">
  <header class="production-heading"><div class="production-heading-main"><strong>{{mode==='craft'?'丹方与药匣':'器谱与本命法宝'}}</strong><button v-if="recipe" class="text-button" @click="emit('track',{kind:'item',id:recipe.output,quantity:Number.isSafeInteger(targetQuantity)&&targetQuantity>0?targetQuantity:1})">成品来源与坊市替代 →</button></div><label><input v-model="future" @change="changeFuture" type="checkbox" aria-label="显示后续生产目录"> 后续境界</label></header>
  <div v-if="!rows.length" class="catalogue-empty production-locked" data-testid="forge-locked"><AssetImage path="art/v2/catalogue/alchemy-v1.webp" asset-id="production-furnace" fit="contain" eager aria-hidden="true"/><div><small>当前{{C.realms[game.core.player.realm].name}} · 炉火未启</small><strong>{{mode==='craft'?'引气入体后可炼丹':'金丹后可在洞府炼器'}}</strong><p>可先翻阅目录，查看不会启炉或消耗物资。</p><button @click="future=true;changeFuture()">查看完整目录</button></div></div>
  <template v-else>
   <nav class="production-choices" :aria-label="mode==='craft'?'配方选择':'器物选择'"><button v-for="row in paged.rows" :key="row.id" :data-testid="(mode==='craft'?'craft-':'forge-')+row.id" :aria-pressed="selected===row.id" @click="select(row.id)"><GameIcon :kind="mode==='craft'?'item':'relic'" :id="row.icon"/><strong>{{row.name}}</strong><small>需{{C.realms[row.min].name}}<template v-if="mode==='forge'&&game.ownedRelics.includes(row.id)"> · 已炼成</template></small></button></nav>
   <CataloguePager :page="paged.page" :pages="paged.pages" :total="paged.total" :label="mode==='craft'?'配方':'器谱'" @change="page=$event"/>
   <div v-if="unit" class="production-stage">
    <div class="production-furnace" :class="{'production-burning':!!activeRuntime,'production-forge':mode==='forge'}"><div class="production-object"><h3><GameIcon :kind="mode==='craft'?'item':'relic'" :id="recipe?.output??selected"/>{{recipe?.name??relic?.name}}</h3><p>{{output?.description??relic?.description}}</p></div><div class="production-art"><AssetImage path="art/v2/catalogue/alchemy-v1.webp" asset-id="production-furnace" fit="contain" eager/><div v-if="mode==='forge'" class="production-relic-object" data-testid="production-relic-object"><GameIcon kind="relic" :id="selected"/><small data-testid="production-relic-state">{{owned?game.loadout.relic===selected?'已装备为本命':'已炼成 · 尚未装备':'器谱示意 · 尚未炼成'}}</small></div></div><div class="production-fire" aria-hidden="true"></div><strong class="production-fire-label" data-testid="production-fire">{{mode==='forge'&&owned?'器纹已凝':fire}}</strong><div class="production-materials" aria-label="单炉材料药匣"><button v-for="(n,id) in unit.items" :key="id" :data-testid="'production-source-'+id" @click="emit('track',{kind:'item',id,quantity:need(String(id))})"><GameIcon kind="item" :id="String(id)"/><strong>{{C.items[id].name}}</strong><span>每{{mode==='craft'?'炉':'件'}} {{n}} · 持有 {{game.core.inventory[id]}}</span><small>保留 {{limits.itemReserves[id]??0}} · 查看来源 →</small></button></div></div>
    <div class="production-decision">
     <p class="production-unit">每{{mode==='craft'?'炉':'件'}} {{unit.stones}} 灵石 · {{unit.months}} 游戏月 · {{unit.months*30}} 秒 · {{mode==='craft'?'固定1枚成品':'只铸造1件'}}</p>
     <details v-if="mode==='craft'" :open="!minimal" class="production-intent-disclosure"><summary v-if="minimal" data-testid="production-intent-toggle">{{cycles==='target'?'目标库存 '+targetQuantity+' · 最多'+targetCycles+'炉':cycles+'炉后停'}} · 调整炉次</summary><div class="production-intent"><label>炉次 <select v-model="cycles" @change="changeCycles" aria-label="炼丹炉次"><option v-for="n in [1,5,20,50]" :key="n" :value="n">{{n}} 炉后停</option><option v-if="cycles!=='target'&&![1,5,20,50].includes(cycles)" :value="cycles">{{cycles}} 炉后停</option><option value="target">库存达到目标即停</option></select></label><template v-if="cycles==='target'"><label>成品库存 <input v-model.number="targetQuantity" @change="changeCycles" type="number" min="1" :max="C.maxQuantity" aria-label="成品目标库存"></label><label>最多 <input v-model.number="targetCycles" @change="changeCycles" type="number" min="1" max="50" aria-label="目标最多炉次">炉</label></template></div></details>
     <div v-else class="production-relic-slot"><strong>当前本命：{{game.loadout.relic?C.relics[game.loadout.relic].name:'尚未装备'}}</strong><span>{{owned?'此器已炼成，不再收取铸造费用。':'拟炼成：'+relic?.name+' · 装备后效果如上'}}</span><button v-if="owned" :data-testid="'equip-relic-'+selected" :disabled="busy||running||!available||!equipQuote?.allowed" @click="emit('act',{type:'EQUIP_RELIC',relic:selected})">{{game.loadout.relic===selected?'已装备':'装备此法宝'}}</button><small v-if="owned&&equipReason" data-testid="production-equip-reason">{{equipReason}}</small></div>
     <button class="production-budget" data-testid="production-limits" @click="openLimits">投入上限 {{limits.stoneBudget}} 灵石 / {{limits.monthBudget}} 月 · 调整预算与保留量</button>
     <div v-if="!owned" class="production-estimate" data-testid="production-estimate"><strong>预计 {{quote?.cycles??0}} {{mode==='craft'?'炉':'件'}} · 灵石消耗 {{quote?.stones??0}} · {{quote?.months??0}} 游戏月</strong><small>耗材：{{costText(quote?.spentItems??{})||'暂无'}}；{{mode==='craft'?'成品 '+(costText(quote?.items??{})||'暂无'):'炼成 '+(quote?.relics.map(id=>C.relics[id].name).join('、')||'暂无')}}</small><small v-if="consumptionWarning" data-testid="production-consumption">单{{mode==='craft'?'炉':'件'}}：{{consumptionWarning}}</small><small>{{quote?.failure?'暂不可安排：'+quote.failure.message:quote?.stopReason?'预计停止：'+quote.stopReason.message:''}}</small></div>
     <button v-if="owned" disabled data-testid="production-start">已炼成，不重复炼制</button><button v-else-if="game.core.world.location==='cave'" class="primary production-start" data-testid="production-start" :disabled="!available||busy||running||!quote?.allowed" @click="emit('start',plan)">{{running?'已有活动进行中，请先暂停':mode==='craft'?'开始这段炼丹':'安排铸造'+relic?.name}}</button><button v-else class="primary production-start" @click="emit('travel',plan)" :disabled="busy||running||!available" data-testid="production-return-cave">前往洞府 · 不自动启炉</button>
     <small class="production-note">在线逐轮保存；刷新后主动继续，不补离线。不自动采购、取材或突破。</small>
    </div>
   </div>
  </template>
  <dialog ref="dialog" class="production-limit-dialog" aria-labelledby="production-limits-title"><h3 id="production-limits-title">这段{{mode==='craft'?'炼丹':'炼器'}}的投入限额</h3><p>只调整待确认安排，点击开始后才保存；材料保留量不会被下一炉消耗。</p><div class="production-limit-fields"><label>累计灵石预算<input v-model.number="draft.stoneBudget" type="number" min="0" aria-label="累计生产灵石预算"></label><label>灵石至少保留<input v-model.number="draft.stoneReserve" type="number" min="0" aria-label="生产灵石保留量"></label><label>累计游戏月预算<input v-model.number="draft.monthBudget" type="number" min="0" aria-label="累计生产游戏月预算"></label><label>余寿至少保留<input v-model.number="draft.remainingMonthsReserve" type="number" min="1" aria-label="生产余寿保留量"></label><label v-for="(_,id) in unit?.items??{}" :key="id">{{C.items[id].name}}保留<input v-model.number="draft.itemReserves[id]" type="number" min="0" :max="C.maxQuantity" :aria-label="C.items[id].name+'保留量'"></label></div><footer><button @click="dialog?.close()">取消调整</button><button class="primary" data-testid="production-apply-limits" @click="applyLimits">应用这些限额</button></footer></dialog>
 </section>
</template>
